fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();

    // If the input is empty or has only one element, return it unchanged.
    if n <= 1 {
        return numbers;
    }

    // Result length is 2 * n - 1
    let mut result = Vec::with_capacity(2 * n - 1);

    for (i, &num) in numbers.iter().enumerate() {
        // Push the current number at even indices
        result.push(num);

        // For all but the last number, push the delimiter after it
        if i < n - 1 {
            result.push(delimiter);
        }
    }

    result
}